"""Bounded character-Trie-aware DataFrame column reordering."""

import bisect
import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Choose a high-reuse column construction and apply bounded exact local repair."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional input reference and the latest returned orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one scalar, replacing scalar missing values with an empty string."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Compute ideal Trie reuse as the LCP sum of lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(cls._lcp(a, b) for a, b in zip(ordered, ordered[1:]))

    @staticmethod
    def _dependency_edges(columns, requested):
        """Convert unambiguous named dependencies into directed column-index edges."""
        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)

        result = []
        seen = set()
        for left, right in requested or []:
            a = positions.get(str(left), [])
            b = positions.get(str(right), [])
            if len(a) == 1 and len(b) == 1 and a[0] != b[0]:
                edge = (a[0], b[0])
                if edge not in seen:
                    seen.add(edge)
                    result.append(edge)
        return result

    @classmethod
    def _constrained_order(cls, m, preference, columns, dependencies):
        """Topologically order columns while using the supplied preference as priority."""
        edges = cls._dependency_edges(columns, dependencies)
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m

        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: pos for pos, column in enumerate(preference)}
        heap = [(rank[i], i) for i in range(m) if indegree[i] == 0]
        heapq.heapify(heap)

        result = []
        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank[nxt], nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _column_statistics(text):
        """Compute length-weighted repeated-value statistics once per column."""
        _, m = text.shape
        result = []

        for col in range(m):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1

            pair_score = 0
            repeat_score = 0
            total = 0
            for value, count in counts.items():
                length = len(value)
                pair_score += length * count * (count - 1)
                repeat_score += length * max(0, count - 1)
                total += length * count

            result.append((pair_score, repeat_score, total))

        return result

    @staticmethod
    def _global_preference(stats, mode):
        """Return one deterministic frequency-ranked global column preference."""
        if mode == 0:
            key = lambda item: (-item[1][0], -item[1][1], -item[1][2], item[0])
        elif mode == 1:
            key = lambda item: (-item[1][1], -item[1][0], -item[1][2], item[0])
        else:
            key = lambda item: (-item[1][2], -item[1][0], -item[1][1], item[0])
        return [j for j, _ in sorted(enumerate(stats), key=key)]

    @staticmethod
    def _conditional_orders(text, base, stats):
        """Partition by one repetitive leading field and rank suffixes inside each group."""
        n, m = text.shape
        if n == 0 or m < 2:
            return [list(base) for _ in range(n)]

        first = max(
            range(m),
            key=lambda col: (stats[col][0], stats[col][1], stats[col][2], -col),
        )
        suffix = [col for col in base if col != first]
        base_rank = {col: pos for pos, col in enumerate(base)}

        groups = {}
        for row in range(n):
            groups.setdefault(text[row, first], []).append(row)

        orders = [None] * n
        for rows in groups.values():
            ranked = []
            for col in suffix:
                counts = {}
                total = 0
                for row in rows:
                    value = text[row, col]
                    counts[value] = counts.get(value, 0) + 1
                    total += len(value)

                pair_score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((-pair_score, -total, base_rank[col], col))

            tail = [item[3] for item in sorted(ranked)]
            order = [first] + tail
            for row in rows:
                orders[row] = order[:]

        return orders

    @staticmethod
    def _serialize_rows(text, orders):
        """Serialize every source row according to its row-specific column order."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @classmethod
    def _legal_swap(cls, order, position, edges):
        """Return whether an adjacent swap preserves all precedence constraints."""
        trial = order[:]
        trial[position], trial[position + 1] = (
            trial[position + 1],
            trial[position],
        )
        location = {column: pos for pos, column in enumerate(trial)}
        return all(location[left] < location[right] for left, right in edges)

    @classmethod
    def _refine(cls, text, orders, strings, columns, dependencies):
        """Run two bounded passes of exact sorted-neighborhood adjacent-swap repair."""
        n, m = text.shape
        if n < 2 or m < 2:
            return orders, strings

        edges = cls._dependency_edges(columns, dependencies)
        entries = sorted((strings[row], row) for row in range(n))
        selected_rows = list(range(min(256, n)))

        def contribution(left, right):
            """Return the LCP contribution for two sorted entries."""
            if left is None or right is None:
                return 0
            return cls._lcp(left[0], right[0])

        for _ in range(2):
            changed = False

            for row in selected_rows:
                old_string = strings[row]
                old_entry = (old_string, row)
                position = bisect.bisect_left(entries, old_entry)

                if position >= len(entries) or entries[position] != old_entry:
                    continue

                old_left = entries[position - 1] if position else None
                old_right = (
                    entries[position + 1]
                    if position + 1 < len(entries)
                    else None
                )
                old_bridge = (
                    entries[position - 1]
                    if position
                    else None
                )
                before = contribution(old_left, old_entry)
                before += contribution(old_entry, old_right)
                if old_left is not None and old_right is not None:
                    before -= contribution(old_left, old_right)

                tested = 0
                for swap_pos in range(m - 1):
                    if tested >= min(12, m * (m - 1) // 2):
                        break
                    tested += 1

                    if not cls._legal_swap(
                        orders[row], swap_pos, edges
                    ):
                        continue

                    trial_order = orders[row][:]
                    trial_order[swap_pos], trial_order[swap_pos + 1] = (
                        trial_order[swap_pos + 1],
                        trial_order[swap_pos],
                    )
                    candidate = "".join(
                        text[row, col] for col in trial_order
                    )

                    if candidate == old_string:
                        continue

                    entries.pop(position)
                    candidate_entry = (candidate, row)
                    new_position = bisect.bisect_left(
                        entries, candidate_entry
                    )

                    new_left = entries[new_position - 1] if new_position else None
                    new_right = (
                        entries[new_position]
                        if new_position < len(entries)
                        else None
                    )

                    after = contribution(new_left, candidate_entry)
                    after += contribution(candidate_entry, new_right)
                    if new_left is not None and new_right is not None:
                        after -= contribution(new_left, new_right)

                    if after > before:
                        entries.insert(new_position, candidate_entry)
                        orders[row] = trial_order
                        strings[row] = candidate
                        changed = True
                        break

                    entries.insert(position, old_entry)

            if not changed:
                break

        return orders, strings

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort source rows by final strings and copy original cells without modification."""
        n, m = source.shape
        row_order = sorted(
            range(n),
            key=lambda row: (serialized[row], row),
        )

        output = np.empty((n, m), dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            output[output_row, :] = [
                source[source_row, col] for col in order
            ]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            output,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate bounded constructions, then refine the winning construction exactly."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)

        for col in range(m):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        stats = self._column_statistics(text)
        candidates = []

        for mode in (0, 1, 2):
            preference = self._global_preference(stats, mode)
            preference = self._constrained_order(
                m, preference, list(df.columns), one_way_dep
            )
            candidates.append([preference[:] for _ in range(n)])

        conditional_base = self._global_preference(stats, 0)
        conditional_base = self._constrained_order(
            m,
            conditional_base,
            list(df.columns),
            one_way_dep,
        )
        candidates.append(
            self._conditional_orders(text, conditional_base, stats)
        )

        best_score = None
        best_orders = None
        best_strings = None

        for orders in candidates:
            serialized = self._serialize_rows(text, orders)
            score = self._trie_score(serialized)

            if best_score is None or score > best_score:
                best_score = score
                best_orders = orders
                best_strings = serialized

        best_orders, best_strings = self._refine(
            text,
            best_orders,
            best_strings,
            list(df.columns),
            one_way_dep,
        )

        result, public_orders = self._materialize(
            df,
            source,
            best_orders,
            best_strings,
        )

        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

